-- supabase/20260903_01_verse_answer_key.sql
-- ============================================================================

-- GENERAT AUTOMAT de scripts/build-answer-key.js — nu edita direct.
-- Regenerează cu: npm run build:answer-key
--
-- Cheia de răspunsuri a serverului. Fără ea, `events.correct` este
-- exact ce a trimis browserul, iar tot recalculul „server-derived" de
-- mai jos nu face decât să reaplice formula peste date neverificate.
-- 1505 versete, 324 pagini.

begin;

create table if not exists public.verse_answers (
  verse_ref    text primary key,
  ordinal      integer not null unique,
  answer       text not null,
  page_index   integer not null,
  page_size    smallint not null,
  chapter_ref  text not null,
  chapter_size smallint not null
);

alter table public.verse_answers enable row level security;
-- Nicio politică: niciun client nu citește tabelul direct. Triggerul și
-- funcțiile de scor sunt SECURITY DEFINER, deci trec pe lângă RLS.

create index if not exists verse_answers_page_idx on public.verse_answers (page_index);

-- Reîncărcare completă: rularea de două ori dă același rezultat.
delete from public.verse_answers;

