      ('Galateni 6:18', array['Câștigați', 'Câștigul', 'Câștiguri', 'Hristos']::text[])
  ) as c(verse_ref, choices)
  join public.verse_answers v using (verse_ref)
  on conflict (verse_ref) do update set
    correct_answer = excluded.correct_answer,
    valid_choices = excluded.valid_choices,
    page_index = excluded.page_index,
    page_size = excluded.page_size,
    chapter_ref = excluded.chapter_ref,
    chapter_size = excluded.chapter_size;
  get diagnostics v_rows = row_count;
  if v_rows <> 686 then
    raise exception 'Catalogul epistolelor: % rânduri în loc de 686. Rulează întâi 20261110_01_epistle_answer_key.sql.', v_rows;
  end if;
  if exists (
    select 1 from public.citim_verse_catalog c
    where c.verse_ref !~ '^[12] Samuel ' and not (c.correct_answer = any(c.valid_choices))
  ) then
    raise exception 'Catalog: răspuns corect absent din variante';
  end if;
end;
$$;
commit;


-- ============================================================================
-- supabase/20261111_01_events_scores_fk_cascade.sql
-- ============================================================================

-- Ștergerea unui cont din dashboard eșua ("Failed to delete user") dacă avea
-- răspunsuri sau scor: în baza live, FK-urile events.user_id și scores.user_id
-- spre auth.users erau NO ACTION. Tabelele fuseseră create manual înainte de
-- migrații, iar 00000000_baseline_schema.sql folosește `create table if not
-- exists`, deci `on delete cascade` din repo nu s-a aplicat niciodată pe live
-- (descoperit pe 2026-11-11). reading_profiles, sesiunile și identitățile se
-- ștergeau deja în cascadă.
--
-- Recreează cele două FK-uri cu `on delete cascade`. Caută numele constrângerii
-- în catalog (pe live nu e cunoscut), așa că merge oricum se numesc. Idempotentă:
-- dacă FK-ul e deja în cascadă, nu face nimic. Nu modifică niciun rând.
begin;

do $$
declare
  v_table text;
  v_constraint record;
begin
  foreach v_table in array array['events', 'scores'] loop
    if exists (
      select 1 from pg_constraint
      where conrelid = ('public.' || v_table)::regclass
        and contype = 'f' and confrelid = 'auth.users'::regclass and confdeltype = 'c'
    ) then
      continue;
    end if;

    for v_constraint in
      select conname from pg_constraint
      where conrelid = ('public.' || v_table)::regclass
        and contype = 'f' and confrelid = 'auth.users'::regclass
    loop
      execute format('alter table public.%I drop constraint %I', v_table, v_constraint.conname);
    end loop;

    execute format(
      'alter table public.%I add constraint %I foreign key (user_id) references auth.users (id) on delete cascade',
      v_table, v_table || '_user_id_fkey'
    );
  end loop;

  -- Verificare finală: ambele FK-uri trebuie să existe și să fie în cascadă.
  if (
    select count(*) from pg_constraint
    where conrelid in ('public.events'::regclass, 'public.scores'::regclass)
      and contype = 'f' and confrelid = 'auth.users'::regclass and confdeltype = 'c'
  ) <> 2 then
    raise exception 'events/scores trebuie să aibă exact câte un FK cascade spre auth.users';
  end if;
end;
$$;

commit;


-- ============================================================================
-- supabase/20261111_02_account_display_names.sql
-- ============================================================================

-- Numele conturilor create fără metadata.username folosește identificatorul
-- intern @citim.app / @test.com, la fel ca Auth.extractUsername din browser.
begin;

create or replace function public.account_display_name(p_user_id uuid)
returns text language sql stable security definer set search_path = public, pg_temp as $$
  select coalesce(
    (select coalesce(
      nullif(trim(u.raw_user_meta_data ->> 'username'), ''),
      case when u.email ~* '@(citim\.app|test\.com)$'
        then nullif(split_part(u.email, '@', 1), '') end
    ) from auth.users u where u.id = p_user_id),
    (select nullif(nullif(trim(s.user_name), ''), 'Utilizator')
      from public.scores s where s.user_id = p_user_id),
    'Utilizator'
  );
$$;

create or replace function public.stamp_account_display_name()
returns trigger language plpgsql security definer set search_path = public, pg_temp as $$
begin
  new.user_name := public.account_display_name(new.user_id);
  return new;
end;
$$;

-- Rulează după verificarea evenimentului, care stabilește user_id autoritativ.
drop trigger if exists zz_events_account_display_name on public.events;
create trigger zz_events_account_display_name before insert on public.events
  for each row execute function public.stamp_account_display_name();
drop trigger if exists zz_scores_account_display_name on public.scores;
create trigger zz_scores_account_display_name before insert or update on public.scores
  for each row execute function public.stamp_account_display_name();

revoke all on function public.account_display_name(uuid) from public, anon, authenticated;
revoke all on function public.stamp_account_display_name() from public, anon, authenticated;

-- Reparație exclusiv de nume, fără recalcularea punctajelor sau a ciclurilor.
update public.scores s set user_name = public.account_display_name(s.user_id)
where s.user_name is distinct from public.account_display_name(s.user_id);

commit;

